import { gsap } from 'gsap';
import { PlaneGeometry, CircleGeometry, CylinderGeometry, SphereGeometry, Color } from 'three/webgpu';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'orrery-node';

  const palette = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(palette.ink ?? '#16161d');
  const paper = new Color(palette.paper ?? '#e8ecf2');
  const accent = new Color(palette.accent ?? '#ff2a38');

  const timelines = [];
  const cleanups = [];

  // Backdrop gradient
  const stops = palette.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = new Color(stops[0].hex);
  const c1 = new Color(stops[1].hex);
  const c2 = new Color(stops[2].hex);

  const uvCenter = subtract(uv(), vec2(0.5));
  const d = length(uvCenter);
  const gradNode = mix(
    mix(color(c0), color(c1), smoothstep(float(stops[0].at), float(stops[1].at), d)),
    color(c2),
    smoothstep(float(stops[1].at), float(stops[2].at), d)
  );

  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial({ colorNode: gradNode });
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  // Linear fog when mounted
  const tryInstallFog = (scene) => {
    if (!scene || scene.fog || !THREE.Fog) return;
    scene.fog = new THREE.Fog(new Color(palette.background ?? '#0b0b10'), 5, 11);
    root.userData.__hasFog = true;
  };
  if (root.parent) tryInstallFog(root.parent);
  root.addEventListener('added', () => {
    let scene = root.parent;
    while (scene && scene.type !== 'Scene' && scene.parent) scene = scene.parent;
    tryInstallFog(scene);
  });

  // Lighting accents
  const rim = new THREE.PointLight(accent, 1.0, 16);
  rim.position.set(-2.2, 1.4, -1.8);
  root.add(rim);

  const fill = new THREE.PointLight(paper, 0.55, 14);
  fill.position.set(0, -1.2, 2.5);
  root.add(fill);

  // Gear assembly
  const gearGroup = new THREE.Group();
  root.add(gearGroup);

  let primaryGear = null;
  let secondaryGear = null;

  const normalizeGear = (srcMeshOrGroup, desiredDiameter) => {
    const box = new THREE.Box3().setFromObject(srcMeshOrGroup);
    const size = new THREE.Vector3();
    box.getSize(size);
    const diameter = Math.max(size.x, size.y, size.z);
    return desiredDiameter / Math.max(diameter, 0.001);
  };

  const startRotation = () => {
    if (!primaryGear || !secondaryGear) return;

    const t1 = gsap.to(primaryGear.rotation, {
      z: `+=${Math.PI * 2}`,
      duration: (Math.PI * 2) / 0.08,
      ease: 'none',
      repeat: -1,
    });

    const t2 = gsap.to(secondaryGear.rotation, {
      z: `-=${Math.PI * 2}`,
      duration: (Math.PI * 2) / Math.abs(-0.142),
      ease: 'none',
      repeat: -1,
    });

    timelines.push(t1, t2);
    cleanups.push(() => { t1.kill(); t2.kill(); });
  };

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const src = gltf.scene ?? gltf;

      src.traverse((o) => {
        if (o.isMesh && o.geometry) {
          const mat = new MeshPhysicalNodeMaterial({
            color: o.material?.color ?? new Color(0x9ca3af),
            roughness: 0.5,
            metalness: 0.55,
            clearcoat: 0.2,
            clearcoatRoughness: 0.3,
            anisotropy: 0.7,
            anisotropyRotation: Math.PI / 2,
            side: THREE.DoubleSide,
          });
          o.material = mat;
          o.castShadow = true;
          o.receiveShadow = true;
        }
      });

      const primaryScale = normalizeGear(src, 1.6);
      primaryGear = src.clone(true);
      primaryGear.scale.setScalar(primaryScale);
      primaryGear.position.set(0, 0, 0);
      gearGroup.add(primaryGear);

      const secondaryScale = normalizeGear(src, 0.9);
      secondaryGear = src.clone(true);
      secondaryGear.scale.setScalar(secondaryScale);
      secondaryGear.position.set(1.15, 0.35, -0.1);
      secondaryGear.rotation.z = 0.11; // phase-locked meshing offset
      gearGroup.add(secondaryGear);

      startRotation();
    }).catch(() => {});
  }

  // Jewel pivot
  const jewelGeo = new SphereGeometry(0.12, 64, 48);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.8,
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.15,
    metalness: 0.0,
    thickness: 0.12,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.06);
  root.add(jewel);

  // Arbor shafts
  const arborGeo = new CylinderGeometry(0.05, 0.05, 0.8, 32);
  const arborMat = new MeshPhysicalNodeMaterial({
    color: ink,
    roughness: 0.6,
    metalness: 0.35,
  });

  const primaryArbor = new Mesh(arborGeo, arborMat);
  primaryArbor.rotation.x = Math.PI / 2;
  primaryArbor.position.set(0, 0, 0);
  root.add(primaryArbor);

  const secondaryArbor = new Mesh(arborGeo, arborMat);
  secondaryArbor.rotation.x = Math.PI / 2;
  secondaryArbor.position.set(1.15, 0.35, -0.1);
  root.add(secondaryArbor);

  // Contact shadow ellipse
  const shadowGeo = new CircleGeometry(1, 64);
  const shadowUV = subtract(uv(), vec2(0.5));
  const shadowAlpha = smoothstep(float(0.35), float(1.0), length(shadowUV)).oneMinus().mul(0.5);
  const shadowNode = vec4(vec3(0.0), shadowAlpha);
  const shadowMat = new MeshBasicNodeMaterial({
    colorNode: shadowNode,
    transparent: true,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(2.6, 1.2, 1);
  shadow.position.set(0.55, -1.2, -0.15);
  root.add(shadow);

  // Text content
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineStr = textItems.find((i) => i.role === 'headline')?.text || 'The going train';
  const captionStr = textItems.find((i) => i.role === 'caption')?.text || '34 COMPONENTS / HAND-FINISHED';

  if (ctx.fontAtlas) {
    const headline = ctx.fontAtlas.createText(headlineStr, {
      fontSize: 0.34,
      color: paper,
      align: 'center',
      maxWidthPx: 520,
      letterSpacingPx: 0,
    });
    headline.position.set(0, -1.9, 0.3);
    root.add(headline);

    const caption = ctx.fontAtlas.createText(captionStr, {
      fontSize: 0.09,
      color: paper,
      align: 'center',
      maxWidthPx: 520,
      letterSpacingPx: 2,
    });
    caption.position.set(0, -2.25, 0.3);
    root.add(caption);

    [headline, caption].forEach((label) => {
      if (label.material) {
        label.material.transparent = true;
        label.material.opacity = 0;
      }
    });

    const tText = gsap.timeline({ delay: 0.2 });
    tText.to(headline.position, { y: -1.7, duration: 0.7, ease: 'power3.out' }, 0);
    tText.to(headline.material || {}, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0);
    tText.to(caption.position, { y: -2.1, duration: 0.7, ease: 'power3.out' }, 0.1);
    tText.to(caption.material || {}, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.1);

    timelines.push(tText);
    cleanups.push(() => tText.kill());
  }

  // Cinematic primitives
  const primList = config.cinematicPrimitives ?? [];
  for (const prim of primList) {
    if (!ctx.primitives?.[prim.name]) continue;
    const result = ctx.primitives[prim.name](root, prim.params ?? {});
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) cleanups.push(() => result.cleanup());
  }

  // Weighted entrance
  root.scale.setScalar(0.96);
  const tRoot = gsap.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  timelines.push(tRoot);
  cleanups.push(() => tRoot.kill());

  root.userData.handlers = {
    pointerenter: () => {},
    pointerleave: () => {},
    click: () => {},
  };

  root.userData.cleanup = () => {
    for (const fn of cleanups) {
      try { fn(); } catch (e) {}
    }
    timelines.forEach((tl) => { try { tl.kill(); } catch (e) {} });

    root.traverse((o) => {
      if (o.isMesh) {
        if (o.geometry) o.geometry.dispose();
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => {
            if (m && m.dispose) m.dispose();
          });
        } else if (o.material && o.material.dispose) {
          o.material.dispose();
        }
      }
    });

    if (root.userData.__hasFog && root.parent && root.parent.fog) {
      root.parent.fog = null;
    }
  };

  return root;
}
